"""Assemble a standalone, offline design gallery. No packages required."""
from pathlib import Path
src=Path(__file__).resolve().parent
root=src.parents[1]
css=(src/'worlds.css').read_text()
js='\n'.join((src/name).read_text() for name in ['catalog.js','scenes.js','materials.js','motion.js','app.js'])
s='''<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="color-scheme" content="light dark"><title>LifeGame — 30 миров продвижения</title><style>CSS</style></head>
<body><header class="gallery"><div class="gallery-top"><span class="brand">LIFE / WORLDS · 30</span><button id="previous" class="arrow" aria-label="Предыдущий мир">‹</button><select id="world-select" aria-label="Выбрать один из 30 вариантов"></select><button id="next" class="arrow" aria-label="Следующий мир">›</button><button id="play">▶ Сценарий</button><button id="download" aria-label="Скачать все 30 миров одним HTML">↓ <span class="download-label">HTML</span></button></div><div class="gallery-bottom"><span class="gallery-count">5 СВЕТ / 25 ДРУГИХ</span><div id="world-chips" style="display:contents"></div></div></header>
<main class="workspace"><article class="device"><header class="masthead"><div><div class="eyebrow" id="world-group"></div><h1 id="world-name"></h1></div><div class="balance" aria-label="Условная награда"><span id="reward-count">0</span> ●</div></header><h2 class="goal-title" id="world-title"></h2><div class="mobile-cause" id="mobile-cause"></div><nav class="view-tabs" role="tablist" aria-label="Вид стратегии"><button id="tab-levels" role="tab" aria-controls="world-panel">Весь маршрут</button><button id="tab-inside" role="tab" aria-controls="world-panel">Внутри этапа</button></nav><section id="world-panel" role="tabpanel" aria-labelledby="tab-levels"><div class="world-canvas"><div id="scene-slot"></div></div><div class="phase-caption"><strong id="phase-name"></strong><span class="phase-state" id="phase-state"></span></div><p class="status" id="status" role="status" aria-live="polite"></p><button id="next-stage" class="next-stage" hidden>Открыть следующий этап →</button></section><div class="task-key">Смысл: жить в выбранном направлении.<br>Дело 1 — выбрать главное. Дело 2 — уделить ему 20 минут.<br>Пропущенное — вернуться к отложенному.</div><p class="download-note">Демо · прогресс только в памяти этой страницы</p></article>
<aside class="explanation"><div class="index" id="world-number"></div><h2 id="composition"></h2><p id="meaning"></p><div class="causes"><div class="cause"><small>Выполнено дело</small><span id="cause-task"></span></div><div class="cause"><small>Вернул пропущенное</small><span id="cause-repair"></span></div><div class="cause"><small>Завершил этап</small><span id="cause-stage"></span></div></div><p style="margin-top:22px;font-size:11px;opacity:.6">Коснись элементов в мире или используй нижние кнопки. Два действия подготавливают переход. Пройденные этапы остаются в маршруте. Переключай вкладки, чтобы увидеть тот же прогресс с другого расстояния.</p></aside></main>
<footer class="dock"><button id="do-task">Следующий шаг</button><button id="repair">Вернуть пропущенное</button><button id="finish">Завершить этап</button><button id="reset" class="reset" aria-label="Сбросить выбранный вариант">↺</button></footer><script>JS</script></body></html>'''
s=s.replace('<style>CSS</style>','<style>\n'+css+'\n</style>').replace('<script>JS</script>','<script>\n'+js+'\n</script>')
p=root/'downloads/strategy-worlds-30.html';p.write_text(s);print(p.relative_to(root),len(s.encode()),'bytes')
